const material=(color,roughness=.8)=>new THREE.MeshStandardMaterial({color,roughness});
const skin=material('#ac7957'),fabric=material('#e8e9db'),navy=material('#183748'),rubber=material('#19282a'),white=material('#fbf7e9');
function shape(parent,geometry,mat,x=0,y=0,z=0,sx=1,sy=1,sz=1){const o=new THREE.Mesh(geometry,mat);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
